-- My Scores — draft quiz-bank questions for mock exams and practice (P5-EXAM #56;
-- owner decision MOCK-RUNNER, 2026-10-27: Claude drafts, reviewers approve).
--
-- 16 topics (Grades 10–12) and 48 original multiple-choice questions in Lao and
-- English for the eight subjects of the published entrance exam blueprints:
-- Mathematics, Physics, Chemistry, Biology, English, Lao language and
-- literature, Geography and History; 3 per topic, 6 per subject. Licence
-- 'original'; the explanations are marked as AI-drafted (QUIZ-003). Every
-- question is a draft without an author: nothing is served until an Academic
-- Reviewer approves it in the Quiz items tab (QUIZ-005, ADMIN-007).
-- Inserted only when the topic code is new for its subject and grade.

insert into public.academic_quiz_topics (subject_id, grade_id, code, name_lo, name_en)
select * from (values
  ((select id from public.academic_subjects where code = 'MATH'), (select id from public.academic_grades where code = 'G10'), 'algebra-equations', 'ສົມຜົນ ແລະ ການແຍກຕົວປະກອບ', 'Equations and factorising'),
  ((select id from public.academic_subjects where code = 'MATH'), (select id from public.academic_grades where code = 'G12'), 'functions-calculus', 'ຟັງຊັນ ແລະ ແຄລຄູລັສ', 'Functions and calculus'),
  ((select id from public.academic_subjects where code = 'PHYS'), (select id from public.academic_grades where code = 'G10'), 'motion-forces', 'ການເຄື່ອນທີ່ ແລະ ແຮງ', 'Motion and forces'),
  ((select id from public.academic_subjects where code = 'PHYS'), (select id from public.academic_grades where code = 'G11'), 'electricity', 'ໄຟຟ້າ', 'Electricity'),
  ((select id from public.academic_subjects where code = 'CHEM'), (select id from public.academic_grades where code = 'G10'), 'atomic-structure', 'ອາຕອມ ແລະ ທາດ', 'Atoms and elements'),
  ((select id from public.academic_subjects where code = 'CHEM'), (select id from public.academic_grades where code = 'G11'), 'acids-bases', 'ອາຊິດ ແລະ ເບສ', 'Acids and bases'),
  ((select id from public.academic_subjects where code = 'BIO'), (select id from public.academic_grades where code = 'G10'), 'cells', 'ເຊວ ແລະ ການສັງເຄາະແສງ', 'Cells and photosynthesis'),
  ((select id from public.academic_subjects where code = 'BIO'), (select id from public.academic_grades where code = 'G11'), 'human-body', 'ຮ່າງກາຍຂອງຄົນ', 'The human body'),
  ((select id from public.academic_subjects where code = 'ENG'), (select id from public.academic_grades where code = 'G10'), 'grammar', 'ໄວຍາກອນ', 'Grammar'),
  ((select id from public.academic_subjects where code = 'ENG'), (select id from public.academic_grades where code = 'G11'), 'vocabulary', 'ຄຳສັບ', 'Vocabulary'),
  ((select id from public.academic_subjects where code = 'LAO'), (select id from public.academic_grades where code = 'G10'), 'lao-writing-system', 'ລະບົບການຂຽນພາສາລາວ', 'The Lao writing system'),
  ((select id from public.academic_subjects where code = 'LAO'), (select id from public.academic_grades where code = 'G11'), 'lao-literature', 'ວັນນະຄະດີລາວ', 'Lao literature'),
  ((select id from public.academic_subjects where code = 'GEO'), (select id from public.academic_grades where code = 'G10'), 'geography-of-laos', 'ພູມສາດຂອງລາວ', 'Geography of Laos'),
  ((select id from public.academic_subjects where code = 'GEO'), (select id from public.academic_grades where code = 'G11'), 'region-and-world', 'ລາວໃນພາກພື້ນ ແລະ ໂລກ', 'Laos in the region and the world'),
  ((select id from public.academic_subjects where code = 'HIST'), (select id from public.academic_grades where code = 'G10'), 'history-of-laos', 'ປະຫວັດສາດລາວ', 'History of Laos'),
  ((select id from public.academic_subjects where code = 'HIST'), (select id from public.academic_grades where code = 'G11'), 'world-history', 'ປະຫວັດສາດໂລກ', 'World history')
) as v(subject_id, grade_id, code, name_lo, name_en)
where v.subject_id is not null and v.grade_id is not null
on conflict (subject_id, grade_id, code) do nothing;

insert into public.academic_quiz_items (topic_id, stem_lo, stem_en, options, correct_key, explanation_lo, explanation_en, explanation_origin, licence, source, status)
select t.id, v.stem_lo, v.stem_en, v.options, v.correct_key, v.explanation_lo, v.explanation_en, 'ai', 'original',
       'Drafted by Claude (AI) for Bitdoin, 2026-10-27; needs reviewer approval', 'draft'
from (values
  ('MATH', 'G10', 'algebra-equations', 'ແກ້ສົມຜົນ 2x + 6 = 14.', 'Solve 2x + 6 = 14.', '[{"key":"A","text_lo":"x = 3","text_en":"x = 3"},{"key":"B","text_lo":"x = 4","text_en":"x = 4"},{"key":"C","text_lo":"x = 5","text_en":"x = 5"},{"key":"D","text_lo":"x = 10","text_en":"x = 10"}]'::jsonb, 'B', 'ລົບ 6 ທັງສອງຂ້າງ (2x = 8), ແລ້ວຫານດ້ວຍ 2: x = 4.', 'Subtract 6 from both sides (2x = 8), then divide by 2: x = 4.'),
  ('MATH', 'G10', 'algebra-equations', 'ຂໍ້ໃດເທົ່າກັບ (x + 3)(x − 3)?', 'Which is equal to (x + 3)(x − 3)?', '[{"key":"A","text_lo":"x² + 9","text_en":"x² + 9"},{"key":"B","text_lo":"x² − 6x − 9","text_en":"x² − 6x − 9"},{"key":"C","text_lo":"x² − 9","text_en":"x² − 9"},{"key":"D","text_lo":"x² + 6x − 9","text_en":"x² + 6x − 9"}]'::jsonb, 'C', 'ຜົນຕ່າງຂອງກຳລັງສອງ: (a + b)(a − b) = a² − b², ສະນັ້ນ x² − 9.', 'Difference of two squares: (a + b)(a − b) = a² − b², so x² − 9.'),
  ('MATH', 'G10', 'algebra-equations', 'ຄຳຕອບຂອງ x² − 5x + 6 = 0 ແມ່ນຫຍັງ?', 'What are the solutions of x² − 5x + 6 = 0?', '[{"key":"A","text_lo":"x = 1 ແລະ x = 6","text_en":"x = 1 and x = 6"},{"key":"B","text_lo":"x = 2 ແລະ x = 3","text_en":"x = 2 and x = 3"},{"key":"C","text_lo":"x = −2 ແລະ x = −3","text_en":"x = −2 and x = −3"},{"key":"D","text_lo":"x = 5 ແລະ x = 6","text_en":"x = 5 and x = 6"}]'::jsonb, 'B', 'x² − 5x + 6 = (x − 2)(x − 3), ສະນັ້ນ x = 2 ຫຼື x = 3.', 'x² − 5x + 6 = (x − 2)(x − 3), so x = 2 or x = 3.'),
  ('MATH', 'G12', 'functions-calculus', 'ຖ້າ f(x) = 2x + 1, f(3) ເທົ່າກັບເທົ່າໃດ?', 'If f(x) = 2x + 1, what is f(3)?', '[{"key":"A","text_lo":"5","text_en":"5"},{"key":"B","text_lo":"6","text_en":"6"},{"key":"C","text_lo":"7","text_en":"7"},{"key":"D","text_lo":"9","text_en":"9"}]'::jsonb, 'C', 'ແທນ x ດ້ວຍ 3: 2 × 3 + 1 = 7.', 'Replace x with 3: 2 × 3 + 1 = 7.'),
  ('MATH', 'G12', 'functions-calculus', 'ອະນຸພັນຂອງ x³ ແມ່ນຫຍັງ?', 'What is the derivative of x³?', '[{"key":"A","text_lo":"x²","text_en":"x²"},{"key":"B","text_lo":"3x²","text_en":"3x²"},{"key":"C","text_lo":"3x","text_en":"3x"},{"key":"D","text_lo":"x⁴/4","text_en":"x⁴/4"}]'::jsonb, 'B', 'ກົດກຳລັງ: ອະນຸພັນຂອງ xⁿ ແມ່ນ n·xⁿ⁻¹, ສະນັ້ນ 3x².', 'Power rule: the derivative of xⁿ is n·xⁿ⁻¹, so 3x².'),
  ('MATH', 'G12', 'functions-calculus', '∫ 2x dx ເທົ່າກັບຫຍັງ?', 'What is ∫ 2x dx?', '[{"key":"A","text_lo":"2 + C","text_en":"2 + C"},{"key":"B","text_lo":"x + C","text_en":"x + C"},{"key":"C","text_lo":"x² + C","text_en":"x² + C"},{"key":"D","text_lo":"2x² + C","text_en":"2x² + C"}]'::jsonb, 'C', 'ອະນຸພັນຂອງ x² ແມ່ນ 2x, ສະນັ້ນປະລິພັນຂອງ 2x ແມ່ນ x² + C.', 'The derivative of x² is 2x, so the integral of 2x is x² + C.'),
  ('PHYS', 'G10', 'motion-forces', 'ຫົວໜ່ວຍ SI ຂອງແຮງແມ່ນຫຍັງ?', 'What is the SI unit of force?', '[{"key":"A","text_lo":"ຈູນ","text_en":"Joule"},{"key":"B","text_lo":"ນິວຕັນ","text_en":"Newton"},{"key":"C","text_lo":"ວັດ","text_en":"Watt"},{"key":"D","text_lo":"ປາສະການ","text_en":"Pascal"}]'::jsonb, 'B', 'ແຮງວັດແທກເປັນນິວຕັນ (N).', 'Force is measured in newtons (N).'),
  ('PHYS', 'G10', 'motion-forces', 'ລົດຄັນໜຶ່ງແລ່ນໄດ້ 120 km ໃນ 2 ຊົ່ວໂມງ. ຄວາມໄວສະເລ່ຍແມ່ນເທົ່າໃດ?', 'A car travels 120 km in 2 hours. What is its average speed?', '[{"key":"A","text_lo":"40 km/h","text_en":"40 km/h"},{"key":"B","text_lo":"60 km/h","text_en":"60 km/h"},{"key":"C","text_lo":"120 km/h","text_en":"120 km/h"},{"key":"D","text_lo":"240 km/h","text_en":"240 km/h"}]'::jsonb, 'B', 'ຄວາມໄວສະເລ່ຍ = ໄລຍະທາງ ÷ ເວລາ = 120 ÷ 2 = 60 km/h.', 'Average speed = distance ÷ time = 120 ÷ 2 = 60 km/h.'),
  ('PHYS', 'G10', 'motion-forces', 'ແຮງໜຶ່ງເຮັດໃຫ້ວັດຖຸ 2 kg ມີຄວາມເລັ່ງ 3 m/s². ແຮງນັ້ນເທົ່າໃດ?', 'A force gives a 2 kg object an acceleration of 3 m/s². What is the force?', '[{"key":"A","text_lo":"1.5 N","text_en":"1.5 N"},{"key":"B","text_lo":"5 N","text_en":"5 N"},{"key":"C","text_lo":"6 N","text_en":"6 N"},{"key":"D","text_lo":"9 N","text_en":"9 N"}]'::jsonb, 'C', 'ກົດທີສອງຂອງນິວຕັນ: F = m × a = 2 × 3 = 6 N.', 'Newton''s second law: F = m × a = 2 × 3 = 6 N.'),
  ('PHYS', 'G11', 'electricity', 'ກະແສ 2 A ໄຫຼຜ່ານຕົວຕ້ານທານ 5 Ω. ແຮງດັນໄຟຟ້າແມ່ນເທົ່າໃດ?', 'A current of 2 A flows through a 5 Ω resistor. What is the voltage across it?', '[{"key":"A","text_lo":"2.5 V","text_en":"2.5 V"},{"key":"B","text_lo":"7 V","text_en":"7 V"},{"key":"C","text_lo":"10 V","text_en":"10 V"},{"key":"D","text_lo":"3 V","text_en":"3 V"}]'::jsonb, 'C', 'ກົດຂອງໂອມ: V = I × R = 2 × 5 = 10 V.', 'Ohm''s law: V = I × R = 2 × 5 = 10 V.'),
  ('PHYS', 'G11', 'electricity', 'ຫົວໜ່ວຍຂອງຄວາມຕ້ານທານໄຟຟ້າແມ່ນຫຍັງ?', 'What is the unit of electrical resistance?', '[{"key":"A","text_lo":"ແອມແປ","text_en":"Ampere"},{"key":"B","text_lo":"ໂວນ","text_en":"Volt"},{"key":"C","text_lo":"ໂອມ","text_en":"Ohm"},{"key":"D","text_lo":"ຄູລອມ","text_en":"Coulomb"}]'::jsonb, 'C', 'ຄວາມຕ້ານທານວັດແທກເປັນໂອມ (Ω).', 'Resistance is measured in ohms (Ω).'),
  ('PHYS', 'G11', 'electricity', 'ອຸປະກອນໜຶ່ງໃຊ້ກະແສ 0.5 A ທີ່ 220 V. ກຳລັງໄຟຟ້າແມ່ນເທົ່າໃດ?', 'A device uses 0.5 A at 220 V. What is its power?', '[{"key":"A","text_lo":"110 W","text_en":"110 W"},{"key":"B","text_lo":"220 W","text_en":"220 W"},{"key":"C","text_lo":"440 W","text_en":"440 W"},{"key":"D","text_lo":"55 W","text_en":"55 W"}]'::jsonb, 'A', 'ກຳລັງ P = V × I = 220 × 0.5 = 110 W.', 'Power P = V × I = 220 × 0.5 = 110 W.'),
  ('CHEM', 'G10', 'atomic-structure', 'ເລກອາຕອມຂອງທາດແມ່ນຈຳນວນ…', 'The atomic number of an element is the number of…', '[{"key":"A","text_lo":"ນິວຕຣອນ","text_en":"neutrons"},{"key":"B","text_lo":"ໂປຣຕອນ","text_en":"protons"},{"key":"C","text_lo":"ຊັ້ນເອເລັກຕຣອນ","text_en":"electron shells"},{"key":"D","text_lo":"ໂມເລກຸນ","text_en":"molecules"}]'::jsonb, 'B', 'ເລກອາຕອມແມ່ນຈຳນວນໂປຣຕອນໃນນິວເຄຼຍ.', 'The atomic number is the number of protons in the nucleus.'),
  ('CHEM', 'G10', 'atomic-structure', 'ສັນຍາລັກທາງເຄມີຂອງໂຊດຽມແມ່ນຫຍັງ?', 'What is the chemical symbol for sodium?', '[{"key":"A","text_lo":"S","text_en":"S"},{"key":"B","text_lo":"So","text_en":"So"},{"key":"C","text_lo":"Na","text_en":"Na"},{"key":"D","text_lo":"Sd","text_en":"Sd"}]'::jsonb, 'C', 'ສັນຍາລັກ Na ມາຈາກຊື່ລາແຕັງ natrium.', 'Sodium’s symbol Na comes from its Latin name, natrium.'),
  ('CHEM', 'G10', 'atomic-structure', 'ໂມເລກຸນນ້ຳ (H₂O) ໜຶ່ງໂມເລກຸນ ມີອາຕອມໄຮໂດຣເຈນຈັກອາຕອມ?', 'How many hydrogen atoms are in one molecule of water (H₂O)?', '[{"key":"A","text_lo":"1","text_en":"1"},{"key":"B","text_lo":"2","text_en":"2"},{"key":"C","text_lo":"3","text_en":"3"},{"key":"D","text_lo":"4","text_en":"4"}]'::jsonb, 'B', 'H₂O ມີໄຮໂດຣເຈນ 2 ອາຕອມ ແລະ ອົກຊີເຈນ 1 ອາຕອມ.', 'H₂O has two hydrogen atoms and one oxygen atom.'),
  ('CHEM', 'G11', 'acids-bases', 'ນ້ຳບໍລິສຸດທີ່ 25 °C ມີ pH ເທົ່າໃດ?', 'What is the pH of pure water at 25 °C?', '[{"key":"A","text_lo":"0","text_en":"0"},{"key":"B","text_lo":"5","text_en":"5"},{"key":"C","text_lo":"7","text_en":"7"},{"key":"D","text_lo":"14","text_en":"14"}]'::jsonb, 'C', 'ນ້ຳບໍລິສຸດເປັນກາງ, ມີ pH 7 ທີ່ 25 °C.', 'Pure water is neutral, with a pH of 7 at 25 °C.'),
  ('CHEM', 'G11', 'acids-bases', 'ອາຊິດທຳປະຕິກິລິຍາກັບເບສ ໄດ້…', 'An acid reacts with a base to form…', '[{"key":"A","text_lo":"ເກືອ ແລະ ນ້ຳ","text_en":"a salt and water"},{"key":"B","text_lo":"ອາຍແກັສໄຮໂດຣເຈນເທົ່ານັ້ນ","text_en":"only hydrogen gas"},{"key":"C","text_lo":"ໂລຫະ","text_en":"a metal"},{"key":"D","text_lo":"ອົກຊີເຈນ","text_en":"oxygen"}]'::jsonb, 'A', 'ການເຮັດໃຫ້ເປັນກາງ: ອາຊິດ + ເບສ → ເກືອ + ນ້ຳ.', 'Neutralisation: acid + base → salt + water.'),
  ('CHEM', 'G11', 'acids-bases', 'ສານລະລາຍທີ່ມີ pH 3 ແມ່ນ…', 'A solution with a pH of 3 is…', '[{"key":"A","text_lo":"ເປັນອາຊິດ","text_en":"acidic"},{"key":"B","text_lo":"ເປັນກາງ","text_en":"neutral"},{"key":"C","text_lo":"ເປັນເບສ","text_en":"basic (alkaline)"},{"key":"D","text_lo":"ເຄັມ","text_en":"salty"}]'::jsonb, 'A', 'pH ຕ່ຳກວ່າ 7 ແມ່ນເປັນອາຊິດ.', 'A pH below 7 is acidic.'),
  ('BIO', 'G10', 'cells', 'ສ່ວນໃດຂອງເຊວ ປ່ອຍພະລັງງານ (ATP) ຫຼາຍທີ່ສຸດ?', 'Which part of the cell releases most of its energy (ATP)?', '[{"key":"A","text_lo":"ນິວເຄຼຍ","text_en":"Nucleus"},{"key":"B","text_lo":"ໄມໂທຄອນເດຣຍ","text_en":"Mitochondrion"},{"key":"C","text_lo":"ຜະໜັງເຊວ","text_en":"Cell wall"},{"key":"D","text_lo":"ແວກຄິວໂອ","text_en":"Vacuole"}]'::jsonb, 'B', 'ການຫາຍໃຈຂອງເຊວໃນໄມໂທຄອນເດຣຍ ປ່ອຍພະລັງງານສ່ວນໃຫຍ່ຂອງເຊວ.', 'Cellular respiration in the mitochondria releases most of the cell’s energy.'),
  ('BIO', 'G10', 'cells', 'ພືດດູດອາຍແກັສໃດ ເພື່ອສັງເຄາະແສງ?', 'Which gas do plants take in for photosynthesis?', '[{"key":"A","text_lo":"ອົກຊີເຈນ","text_en":"Oxygen"},{"key":"B","text_lo":"ໄນໂຕຣເຈນ","text_en":"Nitrogen"},{"key":"C","text_lo":"ກາກບອນໄດອອກໄຊ","text_en":"Carbon dioxide"},{"key":"D","text_lo":"ໄຮໂດຣເຈນ","text_en":"Hydrogen"}]'::jsonb, 'C', 'ພືດໃຊ້ກາກບອນໄດອອກໄຊ ແລະ ນ້ຳ ພ້ອມພະລັງງານແສງ ເພື່ອສ້າງກລູໂຄສ ແລະ ປ່ອຍອົກຊີເຈນ.', 'Plants use carbon dioxide and water, with light energy, to make glucose and release oxygen.'),
  ('BIO', 'G10', 'cells', 'ໂມເລກຸນໃດ ບັນຈຸຂໍ້ມູນທາງພັນທຸກຳ?', 'Which molecule carries genetic information?', '[{"key":"A","text_lo":"ກລູໂຄສ","text_en":"Glucose"},{"key":"B","text_lo":"DNA","text_en":"DNA"},{"key":"C","text_lo":"ແປ້ງ","text_en":"Starch"},{"key":"D","text_lo":"ນ້ຳ","text_en":"Water"}]'::jsonb, 'B', 'DNA ທີ່ພົບສ່ວນໃຫຍ່ໃນນິວເຄຼຍ ບັນຈຸຂໍ້ມູນທາງພັນທຸກຳ.', 'DNA, found mainly in the nucleus, carries genetic information.'),
  ('BIO', 'G11', 'human-body', 'ອະໄວຍະວະໃດ ສູບເລືອດໄປທົ່ວຮ່າງກາຍ?', 'Which organ pumps blood around the body?', '[{"key":"A","text_lo":"ປອດ","text_en":"Lungs"},{"key":"B","text_lo":"ຕັບ","text_en":"Liver"},{"key":"C","text_lo":"ຫົວໃຈ","text_en":"Heart"},{"key":"D","text_lo":"ໝາກໄຂ່ຫຼັງ","text_en":"Kidney"}]'::jsonb, 'C', 'ຫົວໃຈສູບເລືອດຜ່ານເສັ້ນເລືອດ.', 'The heart pumps blood through the blood vessels.'),
  ('BIO', 'G11', 'human-body', 'ເມັດເລືອດໃດ ນຳອົກຊີເຈນ?', 'Which blood cells carry oxygen?', '[{"key":"A","text_lo":"ເມັດເລືອດແດງ","text_en":"Red blood cells"},{"key":"B","text_lo":"ເມັດເລືອດຂາວ","text_en":"White blood cells"},{"key":"C","text_lo":"ເກັດເລືອດ","text_en":"Platelets"},{"key":"D","text_lo":"ເຊວພລາສມາ","text_en":"Plasma cells"}]'::jsonb, 'A', 'ເມັດເລືອດແດງມີຮີໂມໂກລບິນ ເຊິ່ງນຳອົກຊີເຈນ.', 'Red blood cells contain haemoglobin, which carries oxygen.'),
  ('BIO', 'G11', 'human-body', 'ອະໄວຍະວະໃດ ຜະລິດອິນຊູລິນ?', 'Which organ produces insulin?', '[{"key":"A","text_lo":"ກະເພາະອາຫານ","text_en":"Stomach"},{"key":"B","text_lo":"ຕ່ອມແພນຄຣີແອັດ (ໝາກເຂື່ອງ)","text_en":"Pancreas"},{"key":"C","text_lo":"ຫົວໃຈ","text_en":"Heart"},{"key":"D","text_lo":"ຜິວໜັງ","text_en":"Skin"}]'::jsonb, 'B', 'ຕ່ອມແພນຄຣີແອັດ ຜະລິດອິນຊູລິນ ເຊິ່ງຫຼຸດນ້ຳຕານໃນເລືອດ.', 'The pancreas produces insulin, which lowers blood sugar.'),
  ('ENG', 'G10', 'grammar', 'ເລືອກຄຳທີ່ຖືກ: She ___ to school every day.', 'She ___ to school every day.', '[{"key":"A","text_lo":"go","text_en":"go"},{"key":"B","text_lo":"goes","text_en":"goes"},{"key":"C","text_lo":"going","text_en":"going"},{"key":"D","text_lo":"gone","text_en":"gone"}]'::jsonb, 'B', 'ປັດຈຸບັນງ່າຍ ກັບ he/she/it ເພີ່ມ -s: she goes.', 'Present simple with he/she/it adds -s: she goes.'),
  ('ENG', 'G10', 'grammar', 'ຮູບອະດີດຂອງ "go" ແມ່ນຫຍັງ?', 'What is the past tense of "go"?', '[{"key":"A","text_lo":"goed","text_en":"goed"},{"key":"B","text_lo":"gone","text_en":"gone"},{"key":"C","text_lo":"went","text_en":"went"},{"key":"D","text_lo":"going","text_en":"going"}]'::jsonb, 'C', '"go" ເປັນຄຳກິລິຍາອະປົກກະຕິ: go – went – gone.', '"Go" is irregular: go – went – gone.'),
  ('ENG', 'G10', 'grammar', 'ເລືອກຄຳທີ່ຖືກ: If it rains tomorrow, we ___ stay at home.', 'If it rains tomorrow, we ___ stay at home.', '[{"key":"A","text_lo":"will","text_en":"will"},{"key":"B","text_lo":"would","text_en":"would"},{"key":"C","text_lo":"did","text_en":"did"},{"key":"D","text_lo":"were","text_en":"were"}]'::jsonb, 'A', 'ປະໂຫຍກເງື່ອນໄຂແບບທີ 1: if + ປັດຈຸບັນງ່າຍ, will + ກິລິຍາ.', 'First conditional: if + present simple, will + verb.'),
  ('ENG', 'G11', 'vocabulary', 'ຄຳກົງກັນຂ້າມຂອງ "difficult" ແມ່ນຫຍັງ?', 'What is the opposite of "difficult"?', '[{"key":"A","text_lo":"hard","text_en":"hard"},{"key":"B","text_lo":"easy","text_en":"easy"},{"key":"C","text_lo":"long","text_en":"long"},{"key":"D","text_lo":"strong","text_en":"strong"}]'::jsonb, 'B', '"difficult" ໝາຍເຖິງຍາກ; ກົງກັນຂ້າມແມ່ນ "easy" (ງ່າຍ).', '"Difficult" means hard; its opposite is "easy".'),
  ('ENG', 'G11', 'vocabulary', 'ເລືອກຄຳທີ່ຖືກ: A library is a place where you can ___ books.', 'A library is a place where you can ___ books.', '[{"key":"A","text_lo":"cook","text_en":"cook"},{"key":"B","text_lo":"borrow","text_en":"borrow"},{"key":"C","text_lo":"drive","text_en":"drive"},{"key":"D","text_lo":"sell","text_en":"sell"}]'::jsonb, 'B', 'ເຮົາຢືມປຶ້ມຈາກຫ້ອງສະໝຸດ ແລ້ວສົ່ງຄືນພາຍຫຼັງ.', 'You borrow books from a library and return them later.'),
  ('ENG', 'G11', 'vocabulary', 'ເລືອກຄຳທີ່ຖືກ: There are many ___ in the classroom.', 'There are many ___ in the classroom.', '[{"key":"A","text_lo":"student","text_en":"student"},{"key":"B","text_lo":"students","text_en":"students"},{"key":"C","text_lo":"a student","text_en":"a student"},{"key":"D","text_lo":"student’s","text_en":"student’s"}]'::jsonb, 'B', '"many" ຕາມດ້ວຍຄຳນາມພະຫູພົດ: students.', '"Many" is followed by a plural noun: students.'),
  ('LAO', 'G10', 'lao-writing-system', 'ພະຍັນຊະນະລາວ ມີຈັກຕົວ?', 'How many consonant letters does the Lao alphabet have?', '[{"key":"A","text_lo":"21","text_en":"21"},{"key":"B","text_lo":"27","text_en":"27"},{"key":"C","text_lo":"33","text_en":"33"},{"key":"D","text_lo":"44","text_en":"44"}]'::jsonb, 'B', 'ພະຍັນຊະນະລາວ ມີ 27 ຕົວ.', 'The Lao alphabet has 27 consonant letters.'),
  ('LAO', 'G10', 'lao-writing-system', 'ວັນນະຍຸດໃນພາສາລາວ ມີຈັກຕົວ?', 'How many tone marks are used in written Lao?', '[{"key":"A","text_lo":"2","text_en":"2"},{"key":"B","text_lo":"3","text_en":"3"},{"key":"C","text_lo":"4","text_en":"4"},{"key":"D","text_lo":"5","text_en":"5"}]'::jsonb, 'C', 'ພາສາລາວມີວັນນະຍຸດ 4 ຕົວ: ໄມ້ເອກ, ໄມ້ໂທ, ໄມ້ຕີ ແລະ ໄມ້ຈັດຕະວາ.', 'Lao uses four tone marks: ໄມ້ເອກ, ໄມ້ໂທ, ໄມ້ຕີ and ໄມ້ຈັດຕະວາ.'),
  ('LAO', 'G10', 'lao-writing-system', 'ພະຍັນຊະນະລາວ ແບ່ງອອກເປັນຈັກໝວດ?', 'Into how many classes are Lao consonants divided?', '[{"key":"A","text_lo":"2","text_en":"2"},{"key":"B","text_lo":"3","text_en":"3"},{"key":"C","text_lo":"4","text_en":"4"},{"key":"D","text_lo":"6","text_en":"6"}]'::jsonb, 'B', 'ແບ່ງເປັນ 3 ໝວດ: ອັກສອນສູງ, ອັກສອນກາງ ແລະ ອັກສອນຕ່ຳ.', 'Three classes: high, middle and low consonants (ອັກສອນສູງ, ກາງ, ຕ່ຳ).'),
  ('LAO', 'G11', 'lao-literature', 'ຂໍ້ໃດແມ່ນວັນນະຄະດີກາບກອນຄລາສສິກຂອງລາວ?', 'Which of these is a classic Lao epic poem?', '[{"key":"A","text_lo":"ສິນໄຊ","text_en":"Sinxay"},{"key":"B","text_lo":"ໂຣມິໂອ ແລະ ຈູລຽດ","text_en":"Romeo and Juliet"},{"key":"C","text_lo":"ໂອດິດຊີ","text_en":"The Odyssey"},{"key":"D","text_lo":"ດອນກິໂຊ້ດ","text_en":"Don Quixote"}]'::jsonb, 'A', 'ສິນໄຊ ແມ່ນໜຶ່ງໃນວັນນະຄະດີຄລາສສິກທີ່ມີຊື່ສຽງທີ່ສຸດຂອງລາວ.', 'Sinxay (ສິນໄຊ) is one of the best-known classic works of Lao literature.'),
  ('LAO', 'G11', 'lao-literature', 'ພະລັກພະລາມ ແມ່ນສະບັບລາວ ຂອງມະຫາກາບໃດ?', 'Phra Lak Phra Lam is the Lao version of which epic?', '[{"key":"A","text_lo":"ມະຫາພາລະຕະ","text_en":"Mahabharata"},{"key":"B","text_lo":"ຣາມາຍະນະ","text_en":"Ramayana"},{"key":"C","text_lo":"ອີລຽດ","text_en":"Iliad"},{"key":"D","text_lo":"ຊາດົກ","text_en":"Jataka"}]'::jsonb, 'B', 'ພະລັກພະລາມ ແມ່ນການເລົ່າເລື່ອງຣາມາຍະນະ ສະບັບລາວ.', 'Phra Lak Phra Lam (ພະລັກພະລາມ) is the Lao telling of the Ramayana.'),
  ('LAO', 'G11', 'lao-literature', 'ໃນນິທານລາວ ໃຜແມ່ນບັນພະບຸລຸດຂອງກະສັດລາວ?', 'In Lao legends, who is the ancestor of the Lao kings?', '[{"key":"A","text_lo":"ຂຸນບູລົມ","text_en":"Khun Borom"},{"key":"B","text_lo":"ສິນໄຊ","text_en":"Sinxay"},{"key":"C","text_lo":"ຊຽງໝ່ຽງ","text_en":"Xieng Mieng"},{"key":"D","text_lo":"ພະລາມ","text_en":"Phra Lam"}]'::jsonb, 'A', 'ພົງສາວະດານລາວ ເລົ່າວ່າ ຂຸນບູລົມ ແມ່ນບັນພະບຸລຸດຂອງກະສັດລາວ.', 'Lao chronicles tell of Khun Borom (ຂຸນບູລົມ) as the ancestor of the Lao kings.'),
  ('GEO', 'G10', 'geography-of-laos', 'ນະຄອນຫຼວງຂອງ ສປປ ລາວ ແມ່ນບ່ອນໃດ?', 'What is the capital of the Lao PDR?', '[{"key":"A","text_lo":"ຫຼວງພະບາງ","text_en":"Luang Prabang"},{"key":"B","text_lo":"ວຽງຈັນ","text_en":"Vientiane"},{"key":"C","text_lo":"ປາກເຊ","text_en":"Pakse"},{"key":"D","text_lo":"ສະຫວັນນະເຂດ","text_en":"Savannakhet"}]'::jsonb, 'B', 'ນະຄອນຫຼວງວຽງຈັນ ແມ່ນນະຄອນຫຼວງຂອງ ສປປ ລາວ.', 'Vientiane Capital is the capital of the Lao PDR.'),
  ('GEO', 'G10', 'geography-of-laos', 'ແມ່ນ້ຳໃດຍາວທີ່ສຸດ ທີ່ໄຫຼຜ່ານລາວ?', 'Which is the longest river flowing through Laos?', '[{"key":"A","text_lo":"ນ້ຳອູ","text_en":"Nam Ou"},{"key":"B","text_lo":"ແມ່ນ້ຳຂອງ","text_en":"Mekong"},{"key":"C","text_lo":"ນ້ຳງື່ມ","text_en":"Nam Ngum"},{"key":"D","text_lo":"ເຊກອງ","text_en":"Xe Kong"}]'::jsonb, 'B', 'ແມ່ນ້ຳຂອງ ແມ່ນແມ່ນ້ຳທີ່ຍາວທີ່ສຸດໃນລາວ ແລະ ໃນອາຊີຕາເວັນອອກສຽງໃຕ້.', 'The Mekong is the longest river in Laos and in Southeast Asia.'),
  ('GEO', 'G10', 'geography-of-laos', 'ພູທີ່ສູງທີ່ສຸດໃນລາວແມ່ນພູໃດ?', 'What is the highest mountain in Laos?', '[{"key":"A","text_lo":"ພູເບ້ຍ","text_en":"Phou Bia"},{"key":"B","text_lo":"ພູສີ","text_en":"Phou Si"},{"key":"C","text_lo":"ພູເຂົາຄວາຍ","text_en":"Phou Khao Khouay"},{"key":"D","text_lo":"ພູເວົ້າ","text_en":"Phou Vao"}]'::jsonb, 'A', 'ພູເບ້ຍ ຢູ່ແຂວງຊຽງຂວາງ ສູງປະມານ 2,819 ແມັດ.', 'Phou Bia, in Xiangkhouang province, is about 2,819 m high.'),
  ('GEO', 'G11', 'region-and-world', 'ລາວມີຊາຍແດນຕິດກັບຈັກປະເທດ?', 'How many countries share a border with Laos?', '[{"key":"A","text_lo":"3","text_en":"3"},{"key":"B","text_lo":"4","text_en":"4"},{"key":"C","text_lo":"5","text_en":"5"},{"key":"D","text_lo":"6","text_en":"6"}]'::jsonb, 'C', 'ຫ້າປະເທດ: ຈີນ, ຫວຽດນາມ, ກຳປູເຈຍ, ໄທ ແລະ ມຽນມາ.', 'Five: China, Vietnam, Cambodia, Thailand and Myanmar.'),
  ('GEO', 'G11', 'region-and-world', 'ຂໍ້ໃດຖືກຕ້ອງກ່ຽວກັບລາວ?', 'Which statement about Laos is true?', '[{"key":"A","text_lo":"ມີຝັ່ງທະເລຍາວ","text_en":"It has a long sea coast"},{"key":"B","text_lo":"ບໍ່ມີທາງອອກສູ່ທະເລ","text_en":"It is landlocked"},{"key":"C","text_lo":"ເປັນເກາະ","text_en":"It is an island"},{"key":"D","text_lo":"ມີຊາຍແດນຕິດອິນເດຍ","text_en":"It borders India"}]'::jsonb, 'B', 'ລາວເປັນປະເທດດຽວໃນອາຊີຕາເວັນອອກສຽງໃຕ້ ທີ່ບໍ່ມີທາງອອກສູ່ທະເລ.', 'Laos is the only landlocked country in Southeast Asia.'),
  ('GEO', 'G11', 'region-and-world', 'ເສັ້ນໃດແບ່ງໂລກອອກເປັນຊີກໂລກເໜືອ ແລະ ຊີກໂລກໃຕ້?', 'Which line divides the Earth into the Northern and Southern Hemispheres?', '[{"key":"A","text_lo":"ເສັ້ນແວງສູນ","text_en":"Prime Meridian"},{"key":"B","text_lo":"ເສັ້ນສູນສູດ","text_en":"Equator"},{"key":"C","text_lo":"ເສັ້ນທົ່ງຄັນເຊີ","text_en":"Tropic of Cancer"},{"key":"D","text_lo":"ເສັ້ນປ່ຽນວັນທີ","text_en":"Date Line"}]'::jsonb, 'B', 'ເສັ້ນສູນສູດ (ເສັ້ນຂະໜານ 0°) ແບ່ງຊີກໂລກເໜືອ ແລະ ຊີກໂລກໃຕ້.', 'The Equator (0° latitude) divides the Northern and Southern Hemispheres.'),
  ('HIST', 'G10', 'history-of-laos', 'ສປປ ລາວ ສ້າງຕັ້ງຂຶ້ນໃນວັນທີໃດ?', 'On what date was the Lao PDR founded?', '[{"key":"A","text_lo":"2 ທັນວາ 1975","text_en":"2 December 1975"},{"key":"B","text_lo":"12 ຕຸລາ 1945","text_en":"12 October 1945"},{"key":"C","text_lo":"22 ມີນາ 1955","text_en":"22 March 1955"},{"key":"D","text_lo":"20 ມັງກອນ 1949","text_en":"20 January 1949"}]'::jsonb, 'A', 'ສາທາລະນະລັດ ປະຊາທິປະໄຕ ປະຊາຊົນລາວ ໄດ້ຖືກສະຖາປະນາ ໃນວັນທີ 2 ທັນວາ 1975 (ວັນຊາດ).', 'The Lao People’s Democratic Republic was proclaimed on 2 December 1975 (National Day).'),
  ('HIST', 'G10', 'history-of-laos', 'ໃຜເປັນຜູ້ສ້າງຕັ້ງອານາຈັກລ້ານຊ້າງ ໃນປີ 1353?', 'Who founded the Kingdom of Lan Xang in 1353?', '[{"key":"A","text_lo":"ເຈົ້າອະນຸວົງ","text_en":"Chao Anouvong"},{"key":"B","text_lo":"ເຈົ້າຟ້າງຸ່ມ","text_en":"Fa Ngum"},{"key":"C","text_lo":"ພະເຈົ້າໄຊເຊດຖາທິລາດ","text_en":"Setthathirath"},{"key":"D","text_lo":"ພະເຈົ້າສຸລິຍະວົງສາ","text_en":"Souligna Vongsa"}]'::jsonb, 'B', 'ເຈົ້າຟ້າງຸ່ມ ໄດ້ລວບລວມເມືອງລາວ ແລະ ສ້າງຕັ້ງອານາຈັກລ້ານຊ້າງ ໃນປີ 1353.', 'Fa Ngum united the Lao principalities and founded Lan Xang in 1353.'),
  ('HIST', 'G10', 'history-of-laos', 'ພະທາດຫຼວງ ຢູ່ນະຄອນໃດ?', 'In which city is Pha That Luang?', '[{"key":"A","text_lo":"ຫຼວງພະບາງ","text_en":"Luang Prabang"},{"key":"B","text_lo":"ວຽງຈັນ","text_en":"Vientiane"},{"key":"C","text_lo":"ຈຳປາສັກ","text_en":"Champasak"},{"key":"D","text_lo":"ໂພນສະຫວັນ","text_en":"Phonsavan"}]'::jsonb, 'B', 'ພະທາດຫຼວງ ເຊິ່ງເປັນສັນຍາລັກຂອງຊາດ ຢູ່ນະຄອນຫຼວງວຽງຈັນ.', 'Pha That Luang, a national symbol, is in Vientiane Capital.'),
  ('HIST', 'G11', 'world-history', 'ສົງຄາມໂລກຄັ້ງທີສອງ ສິ້ນສຸດໃນປີໃດ?', 'In which year did the Second World War end?', '[{"key":"A","text_lo":"1918","text_en":"1918"},{"key":"B","text_lo":"1939","text_en":"1939"},{"key":"C","text_lo":"1945","text_en":"1945"},{"key":"D","text_lo":"1954","text_en":"1954"}]'::jsonb, 'C', 'ສົງຄາມໂລກຄັ້ງທີສອງ ສິ້ນສຸດໃນປີ 1945.', 'The Second World War ended in 1945.'),
  ('HIST', 'G11', 'world-history', 'ລາວເຂົ້າເປັນສະມາຊິກອາຊຽນ ໃນປີໃດ?', 'In which year did Laos join ASEAN?', '[{"key":"A","text_lo":"1967","text_en":"1967"},{"key":"B","text_lo":"1984","text_en":"1984"},{"key":"C","text_lo":"1997","text_en":"1997"},{"key":"D","text_lo":"2004","text_en":"2004"}]'::jsonb, 'C', 'ລາວເຂົ້າເປັນສະມາຊິກອາຊຽນ ໃນປີ 1997 ພ້ອມກັບມຽນມາ.', 'Laos joined ASEAN in 1997, together with Myanmar.'),
  ('HIST', 'G11', 'world-history', 'ອົງການສະຫະປະຊາຊາດ ສ້າງຕັ້ງຂຶ້ນໃນປີໃດ?', 'In which year was the United Nations founded?', '[{"key":"A","text_lo":"1919","text_en":"1919"},{"key":"B","text_lo":"1945","text_en":"1945"},{"key":"C","text_lo":"1955","text_en":"1955"},{"key":"D","text_lo":"1961","text_en":"1961"}]'::jsonb, 'B', 'ອົງການສະຫະປະຊາຊາດ ສ້າງຕັ້ງຂຶ້ນໃນປີ 1945 ຫຼັງສົງຄາມໂລກຄັ້ງທີສອງ.', 'The United Nations was founded in 1945, after the Second World War.')
) as v(subject, grade, topic_code, stem_lo, stem_en, options, correct_key, explanation_lo, explanation_en)
join public.academic_subjects s on s.code = v.subject
join public.academic_grades g on g.code = v.grade
join public.academic_quiz_topics t on t.subject_id = s.id and t.grade_id = g.id and t.code = v.topic_code
where not exists (select 1 from public.academic_quiz_items i where i.topic_id = t.id and i.stem_lo = v.stem_lo);
